```python
class Order:
    def __init__(self, id: str, customer_id: str):
        self.id = id
        self.customer_id = customer_id
        self._line_items: list[OrderLineItem] = []
        self.status = "draft"
        self._events: list[object] = []

    def add_line_item(self, product_id: str, quantity: int, unit_price: Money) -> None:
        if self.status != "draft":
            raise ValueError("cannot modify a placed order")
        self._line_items.append(OrderLineItem(product_id, quantity, unit_price))

    def total(self) -> Money:
        return sum((li.subtotal() for li in self._line_items), Money(0, "USD"))

    def place(self) -> None:
        if not self._line_items:
            raise ValueError("cannot place an empty order")
        self.status = "placed"
        self._events.append(OrderPlaced(order_id=self.id, total=self.total()))
```

Nothing outside `Order` constructs an `OrderLineItem` directly, and `place()` both enforces an invariant (non-empty order) and raises a domain event as a side effect of the state change.
